<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Request history · Lemonade Profiler</title><link rel="stylesheet" href="<?= $prefix ?>/assets/profiler.css"></head>
<body><header class="top"><a class="brand" href="<?= $prefix ?>"><span class="lemon">L</span> Lemonade <span class="muted">Profiler</span></a><span class="local">LOCAL DEVELOPMENT</span></header>
<main><div class="page-heading"><div><p class="eyebrow">YOUR APPLICATION, OBSERVED</p><h1>Request history</h1><p class="muted">Recent requests from this development environment. Profiles expire automatically.</p></div><a class="button" href="<?= $prefix ?>">Refresh history ↻</a></div>
<section class="panel"><div class="panel-heading"><h2>Latest requests</h2><span class="muted"><?= count($profiles) ?> retained</span></div>
<?php if ($profiles === []): ?><div class="empty"><h3>Waiting for the first request</h3><p>Open an application page, then return here to inspect its profile.</p></div><?php else: ?>
<div class="table-scroll"><table><thead><tr><th>Time</th><th>Status</th><th>Method / route</th><th>Duration</th><th>SQL</th><th>Peak memory</th><th></th></tr></thead><tbody>
<?php foreach ($profiles as $profile): $data = $profile->data; ?>
<tr><td class="muted"><?= gmdate('H:i:s', (int) ($data['created_at'] / 1000000)) ?> UTC</td><td><span class="status <?= $data['status'] >= 400 ? 'bad' : 'good' ?>"><?= $this->escape($data['status']) ?></span></td><td><span class="method"><?= $this->escape($data['method']) ?></span><strong><?= $this->escape($data['route'] ?? $data['path']) ?></strong></td><td><?= $this->ms($data['duration_ms']) ?></td><td><?= $data['sql_count'] ?> <span class="muted">/ <?= $this->ms($data['sql_ms']) ?></span></td><td><?= $this->memory($data['peak_bytes']) ?></td><td><a href="<?= $prefix ?>/request/<?= $this->escape($data['id']) ?>">Inspect ↗</a></td></tr>
<?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<p class="footnote">Only route templates are retained. Request payloads, cookies, query strings and SQL bindings are never stored by the profiler.</p></main></body></html>
